 const select=document.querySelector('#bw-intake-form [name="jobId"]');select?.addEventListener('change',()=>{const next=job(select.value);const summary=document.querySelector('#intake-job-summary'),work=document.querySelector('#intake-work-summary');if(next){summary.textContent=next.ref+' · '+next.device;work.textContent='Work: '+(next.service||'As described in job')+' · Agreed job price: '+money(total(next));const nm=document.querySelector('#bw-intake-form [name="signerName"]');if(nm)nm.value=cust(next.customerId)?.name||''}});
