function initIntakeCanvas(){const canvas=document.getElementById('bw-signature');if(!canvas)return;const ctx=canvas.getContext('2d');ctx.strokeStyle='#15233d';ctx.lineWidth=2.4;ctx.lineCap='round';ctx.lineJoin='round';let drawing=false;intakeHasInk=false;
 const point=e=>{const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height}};
 canvas.addEventListener('pointerdown',e=>{e.preventDefault();canvas.setPointerCapture(e.pointerId);const p=point(e);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x+.05,p.y+.05);ctx.stroke();drawing=true;intakeHasInk=true});
 canvas.addEventListener('pointermove',e=>{if(!drawing)return;e.preventDefault();const p=point(e);ctx.lineTo(p.x,p.y);ctx.stroke()});
 const finish=()=>{drawing=false};canvas.addEventListener('pointerup',finish);canvas.addEventListener('pointercancel',finish);
}
