function saveSettings(e){let v=dataForm(e);Object.assign(db.settings,v);save();render();notify('Settings saved')};function exportJSON(){download('ByteWorks-Hub-Backup-'+today()+'.json',JSON.stringify(db,null,2),'application/json')};function importJSON(e){let f=e.target.files?.[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{let v=JSON.parse(r.result);if(!Array.isArray(v.jobs)||!Array.isArray(v.customers)||!Array.isArray(v.payments))throw Error('Invalid ByteWorks backup');if(!confirm('Replace ALL current local data with this backup?'))return;db={...blank(),...v};save();render();notify('Backup restored')}catch(x){alert('Import failed: '+x.message)}};r.readAsText(f)}
function csvCell(s){return '"'+String(s??'').replace(/"/g,'""')+'"'}function exportCSV(){let rows=[['Job ID','Name','Phone','Device','Service','Status','Date','Labour','Parts','Total','Paid','Owed','Category','Assigned To'],...db.jobs.map(j=>[j.ref,cust(j.customerId)?.name,cust(j.customerId)?.phone,j.device,j.service,j.status,j.date,j.labour,j.parts,total(j),jp(j.id),due(j),j.workType||'',staffLabel(j.assignedTo)])];download('ByteWorks-Jobs-'+today()+'.csv','\ufeff'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function parseCSV(text){let rows=[],row=[],val='',quote=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){val+='"';i++}else quote=!quote}else if(c===','&&!quote){row.push(val);val=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(val);if(row.some(x=>x.trim()))rows.push(row);row=[];val=''}else val+=c}row.push(val);if(row.some(x=>x.trim()))rows.push(row);return rows}
function importCSV(e){let f=e.target.files?.[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{let rows=parseCSV(r.result.replace(/^\ufeff/,'')),heads=rows.shift().map(s=>s.toLowerCase().trim());let at=(row,name)=>row[heads.indexOf(name)]||'';if(!heads.includes('job id')||!heads.includes('device'))throw Error('CSV needs Job ID and Device columns');if(!confirm(`Import ${rows.length} jobs? Existing matching Job IDs will be skipped.`))return;let added=0;rows.forEach(row=>{let ref=at(row,'job id').trim();if(!ref||db.jobs.some(j=>j.ref===ref))return;let name=at(row,'name')||'Unknown customer';let c=db.customers.find(c=>c.name.toLowerCase()===name.toLowerCase());if(!c){c={id:uid(),name,phone:at(row,'phone'),email:'',notes:''};db.customers.push(c)}let grand=n(String(at(row,'total')).replace(/[^\d.-]/g,'')),paid=n(String(at(row,'paid')).replace(/[^\d.-]/g,'')),j={id:uid(),ref,customerId:c.id,device:at(row,'device'),service:at(row,'service'),status:statusList.includes(at(row,'status'))?at(row,'status'):'Booked',date:today(),labour:grand,parts:0,notes:'Imported from CSV; verify itemised costs',existingDamage:'',accessories:'',partSource:'No parts required',partsApproved:'No',workType:at(row,'category')||'Hardware',assignedTo:(staffUsers.find(u=>u.name===at(row,'assigned to'))?.id||'')};db.jobs.push(j);if(paid)db.payments.push({id:uid(),jobId:j.id,date:today(),amount:paid,method:'Imported',reference:'Excel import',notes:'Imported payment total, verify against original records'});added++});db.seq=Math.max(db.seq,...db.jobs.map(j=>{let m=j.ref.match(/^BW-(\d+)$/);return m?Number(m[1])+1:1}));save();render();notify(`Imported ${added} jobs. Review amounts.`)}catch(err){alert('CSV import failed: '+err.message)}};r.readAsText(f)}
