const BW_NOTIF_PREF='byteworks_browser_notifications_v1';
async function enableWorkshopReminders(){
 if(!('Notification' in window))return notify('This browser does not support notifications');
 if(!window.isSecureContext)return notify('Open the HTTPS Vercel website to enable notifications');
 try{
  const permission=await Notification.requestPermission();
  localStorage.setItem(BW_NOTIF_PREF,permission==='granted'?'on':'off');
  if(permission==='granted'){notify('Notifications enabled on this device');testWorkshopNotification();}
  else notify('Notifications were not enabled in browser settings');
 }catch(e){notify('Notification permission error: '+e.message)}
}
async function bwDisplayNotification(title,body,tag){
 if(!('Notification' in window)||Notification.permission!=='granted')return;
 const options={body,tag,icon:'/icons/icon-192.png',badge:'/icons/icon-192.png',data:{url:'/'}};
 try{
  const reg=await navigator.serviceWorker?.ready;
  if(reg?.showNotification)await reg.showNotification(title,options);
  else new Notification(title,options);
 }catch(e){console.warn('Notification display failed',e)}
}
function testWorkshopNotification(){
 if(!('Notification' in window)||Notification.permission!=='granted')return notify('Enable notifications first');
 bwDisplayNotification('ByteWorks notifications are ready','Reminders will appear while ByteWorks Hub is running.','bw-test');
}
let bwReminderTimer=null;
function checkWorkshopReminders(){
 if(!window.BW_CLOUD_READY || !currentTechnician || !db?.appointments || !('Notification' in window) || Notification.permission!=='granted')return;
 if(localStorage.getItem(BW_NOTIF_PREF)!=='on')return;
 const now=Date.now();
 for(const a of db.appointments){
  if(!a.date||!a.time||!a.id)continue;
  const appointmentAt=new Date(`${a.date}T${a.time}:00`).getTime();
  if(!Number.isFinite(appointmentAt))continue;
  const ahead=appointmentAt-now;
  // Remind 30 min beforehand. A newly opened app can catch up to 10 min after.
  if(ahead > 30*60000 || ahead < -10*60000)continue;
  const key='bw-reminder-'+a.id+'-'+a.date+'-'+a.time;
  try{if(localStorage.getItem(key))continue;localStorage.setItem(key,'1')}catch{}
  bwDisplayNotification('ByteWorks appointment',`${a.title||'Appointment'} at ${a.time}`,key);
 }
}
window.addEventListener('bw-cloud-update',()=>setTimeout(checkWorkshopReminders,250));
document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkWorkshopReminders()});
bwReminderTimer=setInterval(checkWorkshopReminders,60000);
